    END_STRUCT
END_TYPE

METHOD FB_Registro : VOID
VAR
    i : INT;
END_VAR

// Inicialización en el primer arranque
IF tiempoAcumulado = T#0s THEN
    indice := -1;
    nEventos := 0;
    posBuffer := 0;
END_IF

// Acumulación del tiempo de ciclo
tiempoAcumulado := tiempoAcumulado + ciclo;

