    // Almacenar el evento en el buffer
    buffer[posBuffer].codigo := evento;
    buffer[posBuffer].marca := tiempoAcumulado;

    // Actualizar el índice y el número de eventos
    indice := posBuffer;
    IF nEventos < 20 THEN
        nEventos := nEventos + 1;
    END_IF

    // Avanzar la posición en el buffer circular
    posBuffer := (posBuffer + 1) MOD 20;
END_IF

