    codigo : INT;  // Código del evento
    marca : TIME;   // Marca de tiempo del evento
END_STRUCT
END_TYPE

METHOD FB_Registro : VOID
    // Inicialización en el primer arranque
    IF NOT (indice = -1) THEN
        tiempoAcumulado := tiempoAcumulado + ciclo;
    END_IF;

    // Registro de nuevo evento
    IF nuevoEvento THEN
        // Guardar el evento en el buffer
        buffer[pos].codigo := evento;
        buffer[pos].marca := tiempoAcumulado;

        // Actualizar el índice y el número de eventos
        IF indice = -1 THEN
            indice := 0;
            nEventos := 1;
        ELSE
            indice := (indice + 1) MOD 20;
            IF nEventos < 20 THEN
                nEventos := nEventos + 1;
            END_IF;
        END_IF;

        // Actualizar la posición para el próximo evento
        pos := indice;
    END_IF;
END_METHOD

TYPE ST_Evento :
STRUCT
    codigo : INT;  // Código del evento
    marca  : TIME; // Tiempo acumulado en el momento del evento
END_STRUCT
END_TYPE

FUNCTION_BLOCK FB_Registro
VAR_INPUT
    evento      : INT;  // Código del evento a registrar
    nuevoEvento : BOOL; // Señal para registrar evento (flanco de subida)
    ciclo       : TIME; // Período de ejecución para el tiempo acumulado
END_VAR

VAR_OUTPUT
    buffer      : ARRAY[0..19] OF ST_Evento; // Buffer circular de eventos
    indice      : INT := -1;                 // Posición del último evento (-1 si está vacío)
    nEventos    : INT := 0;                  // Cantidad de eventos válidos (0 a 20)
END_VAR

VAR
    tiempoAcumulado : TIME := T#0s;          // Tiempo total acumulado desde el arranque
    prevNuevoEvento : BOOL := FALSE;         // Memoria para detección de flanco de subida
END_VAR

// 1. Acumular el tiempo de ejecución en cada ciclo
tiempoAcumulado := tiempoAcumulado + ciclo;

// 2. Detectar transición de FALSE a TRUE en nuevoEvento (flanco de subida)
IF nuevoEvento AND NOT prevNuevoEvento THEN

    // 3. Actualizar el índice de forma circular (0 a 19)
    indice := indice + 1;
    IF indice > 19 THEN
        indice := 0;
    END_IF;

    // 4. Registrar el evento en la posición actual del buffer
    buffer[indice].codigo := evento;
    buffer[indice].marca  := tiempoAcumulado;

    // 5. Actualizar el contador de eventos válidos (saturado en 20)
    IF nEventos < 20 THEN
        nEventos := nEventos + 1;
    END_IF;

END_IF;

// 6. Actualizar la memoria del estado anterior para el detector de flanco
prevNuevoEvento := nuevoEvento;

END_FUNCTION_BLOCK

FUNCTION_BLOCK FB_Registro
VAR_INPUT
    evento : INT;        // Código del evento
    nuevoEvento : BOOL;  // Indica si se ha producido un nuevo evento
    ciclo : TIME;       // Tiempo de ejecución del bloque
END_VAR

VAR_OUTPUT
    buffer : ARRAY[0..19] OF ST_Evento;  // Buffer circular de eventos
    indice : INT;                        // Índice de la posición del último evento registrado
    nEventos : INT;                      // Número de eventos válidos en el buffer
END_VAR

VAR
    tiempoAcumulado : TIME;  // Tiempo acumulado desde el arranque del bloque
    primeraVez : BOOL := TRUE;  // Bandera para inicializar el tiempo acumulado
END_VAR

TYPE
    ST_Evento :
    STRUCT
        codigo : INT;  // Código del evento
        marca : TIME;  // Marca de tiempo del evento
    END_STRUCT
END_TYPE

// Inicialización del tiempo acumulado en la primera ejecución
IF primeraVez THEN
    tiempoAcumulado := T#0s;
    primeraVez := FALSE;
END_IF

// Actualización del tiempo acumulado
tiempoAcumulado := tiempoAcumulado + ciclo;

// Registro de un nuevo evento
IF nuevoEvento THEN
    // Incrementar el índice y ajustarlo al rango del buffer circular
    indice := (indice + 1) MOD 20;

    // Registrar el evento en la posición actual del índice
    buffer[indice].codigo := evento;
    buffer[indice].marca := tiempoAcumulado;

    // Actualizar el número de eventos válidos
    IF nEventos < 20 THEN
        nEventos := nEventos + 1;
    END_IF
END_IF
